import{initializeApp}from"https://www.gstatic.com/firebasejs/10.14.1/firebase-app.js";import{getFirestore,collection,getDocs,query,where,orderBy,limit,serverTimestamp,doc,updateDoc,increment}from"https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore.js";import{getAI,GoogleAIBackend}from"https://www.gstatic.com/firebasejs/10.14.1/firebase-ai.js";import{firebaseConfig}from"./config.js";const app=initializeApp(firebaseConfig),db=getFirestore(app),ai=getAI(app,{backend:new GoogleAIBackend});export const geminiModel=ai.generativeModel({model:"gemini-3-flash-preview",generationConfig:{temperature:.75,maxOutputTokens:1600,topP:.9},systemInstruction:'Eres el asistente inteligente de "Compra Ya", el marketplace líder de Guinea Ecuatorial.\n    Siempre responde en español, de forma profesional, amigable y orientada a ventas.\n    Usa FCFA como moneda. Sé útil, preciso y motivador.'});export{db};export async function obtenerEstadisticasVendedor(e){try{const o=query(collection(db,"productos"),where("vendedorId","==",e)),t=await getDocs(o);let a={totalProductos:0,totalVisitas:0,totalLikes:0,productosPorCategoria:{},productosTrending:[]};t.forEach(e=>{const o=e.data();a.totalProductos++,a.totalVisitas+=o.visitas||0,a.totalLikes+=o.likes||0,o.categoria&&(a.productosPorCategoria[o.categoria]=(a.productosPorCategoria[o.categoria]||0)+1),((o.visitas||0)>40||(o.likes||0)>15)&&a.productosTrending.push({id:e.id,...o})});const i=`Analiza estas estadísticas de un vendedor en Compra Ya (Guinea Ecuatorial) y genera un informe útil:\n\nTotal productos: ${a.totalProductos}\nVisitas totales: ${a.totalVisitas}\nLikes totales: ${a.totalLikes}\nCategorías: ${JSON.stringify(a.productosPorCategoria)}\n\nDevuelve un JSON con: \n{\n  "resumen": "texto corto",\n  "fortalezas": ["lista"],\n  "recomendaciones": ["lista"],\n  "productosQueDeberianEstarTrending": ["títulos o IDs"]\n}`,n=(await geminiModel.generateContent(i)).response.text();return{...a,analisisIA:n}}catch(e){return console.error("Error en estadísticas:",e),null}}export async function recomendarPrecioOptimo(e,o,t,a=""){try{const i=`Analiza este producto y recomienda el precio óptimo de venta en Guinea Ecuatorial:\n\nTítulo: ${e}\nCategoría: ${o}\nPrecio actual: ${t} FCFA\nDescripción: ${a||"No disponible"}\n\nConsidera competencia local, poder adquisitivo y demanda actual.\nDevuelve SOLO un JSON válido:\n{\n  "precioRecomendado": number,\n  "rangoSugerido": "min - max",\n  "justificacion": "texto breve y convincente",\n  "potencialVentas": "alto/medio/bajo"\n}`,n=await geminiModel.generateContent(i),r=n.response.text().match(/\{[\s\S]*\}/);return r?JSON.parse(r[0]):null}catch(e){return console.error("Error recomendando precio:",e),{precioRecomendado:t,rangoSugerido:"Sin datos",justificacion:"Error en análisis IA"}}}export async function verificarProductosTrending(e){try{const o=query(collection(db,"productos"),where("vendedorId","==",e),where("visitas",">",25)),t=await getDocs(o);let a=[];return t.forEach(e=>{const o=e.data();(o.visitas>60&&(o.likes||0)>12||o.visitas>100)&&a.push({productoId:e.id,titulo:o.titulo||o.Título,mensaje:"🚀 Este producto está trending y recibiendo muchas visitas",tipo:"trending",visitas:o.visitas,likes:o.likes||0})}),a}catch(e){return console.error("Error verificando trending:",e),[]}}export async function generarDescripcionAvanzada(e,o,t,a=[]){let i=[{text:`Eres un vendedor experto. Genera una descripción comercial atractiva y detallada para Compra Ya (Guinea Ecuatorial):\n\nTítulo: ${e}\nCategoría: ${o}\nPrecio: ${t} FCFA\n\nResponde solo con la descripción final en español, usando emojis, beneficios y llamada a acción.`}];if(a&&a.length>0){(await Promise.all(a.map(e=>window.fileToBase64(e)))).forEach(e=>{i.push({inlineData:{mimeType:"image/jpeg",data:e.split(",")[1]}})})}try{return(await geminiModel.generateContent({contents:[{parts:i}]})).response.text()}catch(e){return console.error(e),"No se pudo generar la descripción en este momento."}}console.log("%c🤖 Sistema IA Avanzado cargado correctamente (Gemini 3 Flash)","color:#00ff88; font-weight:bold");